    "profile": "浙江蓝途户外用品股份有限公司，注册资金1000万。成立于2017年，前身是三门星途户外成立于2002年，经过20年的服装生产经验积累。现如今三门蓝途已经是一家拥有1600多员工，厂房面38000多平方，现货储备快速发货、DIY定制满足客户个性需求，年产销300多万件冲锋衣等产品。公司以冲锋衣校服、冲锋衣工作服、休闲软壳衣夹克、皮肤风衣、速干衣裤、冲锋裤、隔离衣、口罩防疫物资等为主要生产经营。目前重点运营的品牌为“蓝途”，有完整的生产管理流程（5S生产管理）、专业打样设计团队（设计版师5人、打样12人），和各大户外品牌、校服定制公司均有合作。公司还充分利用蓬勃发展的电商市场开展业务活动，顺应市场需求多品种、小批量的服装生产模式，从原有的批量生产线下销售的模式转变成了网上定制线下生产的模式，企业组建电商团队，在众多电商平台开设了多家网店，无论批发、零售均有涉及。这种线上线下融合的电子商务模式减少了产业链中间环节，满足了消费者的个性（DIY）需求。",
    "businessScope": "一般项目：服装制造；服饰制造；特种劳动防护用品生产；劳动保护用品生产；产业用纺织制成品制造；鞋制造；箱包制造；服装服饰批发；鞋帽批发；第一类医疗器械销售；服装服饰零售；鞋帽零售；货物进出口；第一类医疗器械生产；医护人员防护用品生产（Ⅰ类医疗器械）；日用口罩（非医用）生产；技术进出口；日用口罩（非医用）销售；医用口罩零售；医用口罩批发；潜水救捞装备制造；潜水救捞装备销售；互联网销售（除销售需要许可的商品）（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）。许可项目：第二类医疗器械生产；医用口罩生产（依法须经批准的项目，经相关部门批准后方可开展经营活动，具体经营项目以审批结果为准）。"
