    "email": "malinxi321@126.com;3209554852@qq.com;1071507994@qq.com;matingmolly@126.com;962363279@qq.com;zhang.xueying@toread.com;zhu.mantang@toread.com.cn;ir300005@toread.com.cn",
    "companyType": "",
    "people": "",
    "scale": "M(中型)",
    "profile": "探路者控股集团股份有限公司成立于1999年，历经二十二年的发展，逐渐成长为拥有过硬科研实力的综合型户外用品集团公司。在2009年作为首批企业之一，成功登陆中国创业板(股票代码:300005),公司以持续的创新突破引领行业发展，成为中国户外用品市场的领军品牌。旗下拥有:探路者TOREAD、TOREAD.X、TOREADkids多个子品牌，产品覆盖多个运动类目，包括极限、徒步、跑步、旅行、滑雪等众多产品系列，针对不同年龄段和应用场景差异进行设计，满足消费者的需求。公司聚焦核心科技，强化融合创新，注重成果转化，坚持“深入科技研究、整合优势资源、打造科技平台”的科研方向。自公司成立以来，获得国内外行业科技、研发和设计奖项共计126项，其中包括中国纺织工业联合会科学技术进步奖、全球体育及户外用品博览会(ISPO)设计奖、全球体育及户外用品博览会(ISPO)功能性纺织品趋势大奖等奖项;同时公司积极参与国行标准起草26项，其中GB/T32614-2016户外运动服装冲锋衣国家标准制定，获得中国纺织工业联合会科学技术进步奖。在探路者探索、担当、协同、诚信、学习的价值观内核下，公司对内建立了独特的员工行为准则，对外将此理念延伸到同合作伙伴及社会关系的处理中，将生态环境保护和社会公益责任作为企业文化的重要组成部分，从保护藏羚羊、保护滇金丝猴、珠峰5000米雪线以上垃圾清理、汶川地震、玉树地震、九寨沟地震、新冠疫情，河南暴雨等，每一次都有探路者的身影。",
    "businessScope": "项目投资；生产帐篷、睡袋、服装、鞋帽、背包、水壶、非医用防护服；研究、设计、开发帐篷、睡袋、登山器材、服装、鞋帽、背包；销售帐篷、睡袋、登山器材、服装、防寒服装、鞋帽、非医用防护服、医疗器械（仅限I类、II类）、羽绒及羽绒制品、背包、体育用品（不含弩）、文化用品、工艺品、日用百货、办公设备、五金交电、电子产品、半导体器件专用设备、电子元器件；普通货物运输；信息咨询（不含中介）；市场调查；货物进出口、技术进出口、代理进出口；出租商业用房、出租办公用房（不得作为有形市场经营用房）；技术检测；旅游咨询；制造半导体器件专用设备、电子元器件与机电组件设备、集成电路；集成电路设计；计算机系统服务；软件开发；技术服务、技术开发、技术转让、技术推广、技术咨询；生产第二类医疗器械。（“1、未经有关部门批准，不得以公开方式募集资金；2、不得公开开展证券类产品和金融衍生品交易活动；3、不得发放贷款；4、不得对所投资企业以外的其他企业提供担保；5、不得向投资者承诺投资本金不受损失或者承诺最低收益”；市场主体依法自主选择经营项目，开展经营活动；生产第二类医疗器械以及依法须经批准的项目，经相关部门批准后依批准的内容开展经营活动；不得从事国家和本市产业政策禁止和限制类项目的经营活动。）"
