    "profile": "深圳减字科技有限公司(Janez T)是中国香港减字控股旗下子公司，主要负责WaveBetter、BananaUmbrella等品牌的设计、研发、生产、品牌维护与推广、销售等业务。抱着完美主义的态度做产品和服务，在海内外市场迅速发展，并且获得红杉资本（Sequoia Capital）的投资。现营品牌：WaveBetterWaveBetter是减字控股旗下的针对亚洲人肤质开发的全新美容护肤品牌。Wavebetter系列产品在日本、新加坡地区广受好评。WaveBetter在2012年7月进入中国大陆市场，经过一年多的发展，在仪器护肤市场，成为了领导者和创新者。与天猫、唯品会、魅力惠以及各银行积分商城等优质渠道均有良好合作，并且目前共有26家高品质实体店进行销售。2012年营业额实现了8000万元的突破，其中直营的WaveBetter天猫旗舰店占营业额的约50%，并且有强劲的增长势头。BananaUmbrella生产BananaUmbrella的中国香港老字号制伞厂创办于十九世纪末，是中国香港最早的纯手工制伞工厂，最早引入德国制伞辅助机器，对品质严格要求认证做好每一把伞，其品牌伞的品质倍受消费者认可，2000年，制伞厂的产量多年稳居全球第二。减字控股于2011年初正式完成对百年伞厂的全面收购。减字投入巨额的研发资金，在原先制伞工厂的精湛技术和专利之上，反其道而行，在制作上重回全手工制作，在各类结构、面料、涂层、处理工艺、材料上投入巨额资金研发和购买专利。推出了全新的BananaUmbrella品牌。这更像是一个百年老厂重新迈上了时代的舞台。",
