    "profile": "浙江星华新材料集团股份有限公司成立于2003年，专注于反光材料和反光服生产、研发、销售。产品覆盖:反光布、反光热贴、反光织带包边、反光丝、反光背心、反光雨衣夹克等，并通过国标、欧美国际标准认证。拥有数种印花反光面料专利，以及新研发的柔软型、七彩炫彩、冲孔等时尚休闲功能面料。公司拥有多个现代化工厂，拥有多条反光布生产线，可在最短时间完成各种紧急大量订单。星华积极整合上下游产业链，具备自主研发、稳定生产各类反光产品的专业实力，可为客户提供质量稳定的产品，快速满足客户各种需求。自成立以来，星华凭借诚信经营，赢得国内外客户多年的信赖与持续合作，产品远销全球各主要国家和地区。在此基础上，公司以质量为根本，以市场为导向，以服务为核心，不断创新品牌产品，精心打造“CNSS”品牌，点此查看我们的反光认证证书及企业荣誉。公司主营业务为反光材料及其制品的研发、设计、生产及销售。公司主要生产的反光材料为反光布，产品广泛应用于职业安全防护、个人安全防护、休闲服饰、功能型面料、运动用品、户外用品、箱包、鞋类等领域。公司自成立以来一直致力于反光材料的研发、生产应用和市场开发，经过多年自主研发，公司在技术创新、工艺改进、生产管理、质量控制等方面积累了丰富的经验。公司系国家级技术企业、浙江省创新型示范中小企业、浙江省专利示范企业，公司研发中心被认定为浙江省省级企业研究院。截止2023年12月31日，公司在核心设备、工艺、产品等方面拥有专利198项，其中发明专利31项(国内发明专利29项，美国发明专利1项、欧洲发明1项)、实用新型专利72项、外观专利95项，上述专利涵盖了从产品设计、工艺技术、原材料制备、生产设备设计与制造等各个方面。公司产品已取得出口欧洲、美国、加拿大、澳大利亚等国家和地区的关于质量、环保、安全等方面的认证，包括CE认证、SGS认证、美国UL实验室安全认证等，并通过REACH、ROHS、OEKO-TEX等欧盟国家有毒或有害物质检测认证。公司品牌被评为“浙江省著名商标”、“杭州市著名商标”,公司被列为浙江省中小型“隐形冠军”培育对象。",
    "businessScope": "一般项目：新材料技术研发；新型膜材料制造；新型膜材料销售；专用化学产品制造（不含危险化学品）；专用化学产品销售（不含危险化学品）；合成材料制造（不含危险化学品）；合成材料销售；高性能纤维及复合材料制造；高性能纤维及复合材料销售；电子专用材料研发；电子专用材料制造；电子专用材料销售；石墨烯材料销售；石墨及碳素制品制造；石墨及碳素制品销售；服装辅料制造；服装辅料销售；合成纤维销售；针纺织品销售；针纺织品及原料销售；塑料制品销售；服装服饰批发；服装服饰零售；劳动保护用品销售；功能玻璃和新型光学材料销售；新兴能源技术研发；集中式快速充电站；合同能源管理；货物进出口；技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广；软件销售；网络设备销售；物联网设备销售；网络技术服务；光通信设备销售；通信设备销售；服装制造；服饰制造（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）。"
